def required_dependencies(stage, role):
    if stage == 'templates':return set()
    if stage == 'manifest':return set(TEMPLATE_ROLES)|{'profile'}
    if stage == 'capture':return {'capture_template','metadata_manifest','profile','static','metadata_peer'}
    if stage == 'phase_bound':return {role.replace('_bound','_template'),'capture_bound','metadata_binding','metadata_bound_review'}
    if stage == 'phase_binding':return set(TEMPLATE_ROLES[1:])|set(PHASE_BOUND_ROLES)|{'capture_bound','metadata_binding','metadata_bound_review'}
    raise ValueError('unknown deferred metadata stage')
